import React from "react";
function Button(){
    return(
<div className="flex flex-col items-start mr-3">
	<span className="text-white text-6xl font-bold mb-12" >
		{"Ready to Empower Your Classroom with Shiksha Robot?"}
	</span>
	<span className="text-white text-[34px] font-bold mb-[35px] mx-[62px]" >
		{"Transform the way Spoken English is taught. Contact us today to bring Shiksha: The Gen 2 Spoken English Teaching Robot to your school!"}
	</span>
	<img
		src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/0d2z5icp_expires_30_days.png"} 
		className="w-[783px] h-[514px] ml-2.5 object-fill"
	/>
	<button className="flex items-center bg-[#FFDD15] text-left py-[15px] px-[30px] ml-[411px] gap-[15px] rounded-[33px] border-0"
		onClick={()=>alert("Pressed!")}>
		<img
			src={"https://storage.googleapis.com/tagjs-prod.appspot.com/v1/9w1KRIs84F/ctaazjp0_expires_30_days.png"} 
			className="w-12 h-12 rounded-[33px] object-fill"
		/>
		<span className="text-black text-xl font-bold" >
			{"Contact us"}
		</span>
	</button>
</div>
    );
}
export default Button;
